package oepul.o6_17

import data.o17_tables as tab
import rego.v1

alpine_modulation(area, driven_rgve) := modulation(min([area, driven_rgve])) if {
	area > 0
	driven_rgve > 0
}

exemption(p) if {
	some r in tab.management_exemptions
	input.farm.year >= 2023
	input.farm.year <= r.last_year
	p.management.exemption_use in r.uses
	p.management.exemption_measure in r.measures
}

# Erfüllung der allgemeinen Mindestbewirtschaftung. Spezifische Auflagen der
# jeweiligen Ausnahme werden in ihrer eigenen Maßnahme geprüft.
management_met(p) if exemption(p)

management_met(p) if {
	a := p.management
	a.category in {"Acker ohne Ackerfutter", "Geschützter Anbau"}
	a.proper_establishment
	a.annual_care
	a.harvest_removed_percent >= 85
}

management_met(p) if {
	p.management.proper_establishment
	p.management.annual_care
	drought_harvest_exception(p)
}

management_met(p) if {
	a := p.management
	a.category in {"Dauerkultur", "Spezialkultur", "Wein"}
	a.proper_establishment
	a.annual_care
	a.harvested_and_removed
}

management_met(p) if {
	a := p.management
	a.category in {"Grünland", "Ackerfutter"}
	p.mfa_use != "Bergmähder"
	a.whole_mown_and_removed_this_year
}

management_met(p) if {
	a := p.management
	a.category in {"Grünland", "Ackerfutter"}
	p.mfa_use != "Bergmähder"
	a.whole_grazed_this_year
}

management_met(p) if {
	p.mfa_use == "Bergmähder"
	p.management.whole_mown_and_removed_within_two_years
}

management_met(p) if {
	a := p.management
	a.category == "Aus der Produktion genommen"
	a.maintenance_within_two_years
	green_cover_ok(a)
}

green_cover_ok(a) if a.green_cover_established
green_cover_ok(a) if a.permitted_self_greening

parcel_exclusions[p.parcel_id] contains "Ausgeschlossene Schlagnutzung" if {
	some p in input.land.parcels
	p.mfa_use in tab.excluded_uses
}

parcel_exclusions[p.parcel_id] contains "Keine aktive Bewirtschaftung" if {
	some p in input.land.parcels
	p.oepul_assessment.active_production == false
	not exemption(p)
}

parcel_exclusions[p.parcel_id] contains reason if {
	some p in input.land.parcels
	some key, reason in {"applied_for_17": "Maßnahme nicht beantragt", "correctly_identified": "Fläche falsch identifiziert", "predominantly_agricultural": "Nicht hauptsächlich landwirtschaftlich genutzt"}
	p.oepul_assessment[key] == false
}

parcel_exclusions[p.parcel_id] contains reason if {
	some p in input.land.parcels
	some key, reason in {"gloez_landscape_element": "GLÖZ-Landschaftselement", "restricted_national_park": "Relevante Nationalparkauflage", "approved_trial_prevents_compliance": "Genehmigter Versuch mit Auflagenabweichung", "op_for_17": "OP für Maßnahme 17"}
	p.oepul_assessment[key]
}

parcel_exclusions[p.parcel_id] contains "Nationalpark mit flächenbezogenem Ausschluss" if {
	some p in input.land.parcels
	p.oepul_assessment.national_park in {"Neusiedlersee", "Donau-Auen"}
}

parcel_exclusions[p.parcel_id] contains "Code OP oder VF" if {
	some p in input.land.parcels
	some c in p.mfa_codes
	c in {"OP", "VF"}
}

incompatible_pair contains [r.left, r.right] if {
	some r in tab.farm_conflicts
	ms := input.farm.o6_17.active_measures
	r.left in ms
	r.right in ms
	not partial_exception(r, ms)
}

partial_exception(r, ms) if {
	r.partial_bio_exception
	"BIO-Teilbetrieb" in ms
}

course_certificate_due if {
	c := input.documentation.course_confirmation
	c.ama_requested
	c.provider_submitted == false
	c.farm_submitted == false
}

regular_divrs_use(u, _) if u.cleaning_cut == false

regular_divrs_use(u, m) if {
	u.cleaning_cut
	m.first_application_year == false
}

regional_management_met(p) if {
	m := p.operations.divrs_management
	m.mulched == false
	m.removed
	is_array(m.uses)
	is_array(m.fertilisers)
	every f in m.fertilisers { f in {"Festmist", "Festmistkompost"} }
	every u in m.uses {
		date_ok(u.date)
		startswith(u.date, sprintf("%d-", [input.farm.year]))
		is_boolean(u.cleaning_cut)
	}
	is_boolean(m.first_application_year)
	uses := [u | some u in m.uses; regular_divrs_use(u, m)]
	count(uses) <= 2
	every u in uses { substring(u.date, 5, 5) >= "07-15" }
}

# Nur Codierung und betriebliche Voraussetzungen der vorzeitigen/zusätzlichen
# Ackernutzung. Der jeweilige Flächenanteil bleibt bei UBB/BIO unbezahlt.
coded_early_use(p) if {
	input.farm.year == 2026
	p.land_use == "arable"
	p.constraints.biodiversity_area.is_biodiversity_area
	a := p.div_2026
	a.other_restrictive_conditions == false
	coding_needed(a)
	code := {"UBB": "OPUBB", "BIO": "OPBIO", "BIO-Teilbetrieb": "OPBIO"}[a.partner]
	code in p.mfa_codes
}

coding_needed(a) if {
	a.early_use
	a.mowed_beyond_free_quarter
}

coding_needed(a) if {
	a.early_use
	a.early_grazing
}

coding_needed(a) if a.third_arable_use

div_minimum(mown_ha) := mown_ha * 0.07 if mown_ha > 2

else := 0 if mown_ha >= 0

div_field_minimum(total_mown, field_mown) := 0.15 if {
	total_mown >= 10
	field_mown > 5
}

else := 0 if {
	total_mown >= 0
	field_mown >= 0
}

div_field_shortfalls contains f.field_id if {
	companion
	some f in input.land.div_field_blocks
	f.eligible_div_ha + f.assigned_gloez_lse_ha < div_field_minimum(agl_mown_ha, f.mown_excluding_mountain_ha)
}

bio_cycle_rate := 40 if {
	input.farm.year >= 2025
	input.farm.year <= 2028
	some m in input.farm.o6_17.active_measures
	m in {"BIO", "BIO-Teilbetrieb"}
	stocking_density >= 0.3
	stocking_density < 1.4
	bio_grass := input.land.bio_circular_grass
	bio_grass.mown_ha > 0
	100 * bio_grass.div_or_species_rich_union_ha > 8 * bio_grass.mown_ha
	bio_grass.div_or_species_rich_union_ha <= bio_grass.mown_ha
}

div_grass_exception(p) if {
	input.farm.year == 2026
	p.land_use == "grassland"
	p.constraints.biodiversity_area.is_biodiversity_area
	g := p.div_grass
	g.early_exception
	g.other_restrictive_conditions == false
	code := {"UBB": "OPUBB", "BIO": "OPBIO", "BIO-Teilbetrieb": "OPBIO"}[g.partner]
	code in p.mfa_codes
}

div_rest_days(p) := 49 if {
	p.div_grass.variant == "DIVNFZ"
	div_grass_exception(p)
}

else := 63 if p.div_grass.variant == "DIVNFZ"

date_ns(d) := time.parse_rfc3339_ns(sprintf("%sT00:00:00Z", [d]))
phenology_2026(n) if n == 0

phenology_2026(n) if {
	n >= 4
	n <= 7
	round(n) == n
}

divsz_day(p) := date_ns(p.div_grass.use_date) if {
	input.farm.year == 2026
	p.land_use == "grassland"
	p.div_grass.variant == "DIVSZ"
	startswith(p.div_grass.use_date, "2026-")
	phenology_2026(p.div_grass.phenology_days)
}

divsz_use_allowed(p) if {
	g := p.div_grass
	divsz_day(p) >= date_ns("2026-07-15") - (g.phenology_days * 86400000000000)
}

divsz_use_allowed(p) if {
	g := p.div_grass
	g.comparable_second_cut_started
	divsz_day(p) >= date_ns("2026-06-15") - (g.phenology_days * 86400000000000)
}

divsz_use_allowed(p) if {
	div_grass_exception(p)
	g := p.div_grass
	g.comparable_second_cut_started
	divsz_day(p) >= date_ns("2026-06-15") - ((14 + g.phenology_days) * 86400000000000)
}

conditionality_findings contains f.domain if {
	some f in input.documentation.conditionality_findings
	f.year == input.farm.year
	f.official_noncompliance
}

permitted_conversion(e) if {
	e.old_use in {"A", "S", "WI", "WT"}
	e.new_use in {"G", "D"}
}

permitted_conversion(e) if {
	e.old_use in {"G", "D"}
	e.new_use == "L"
}

permitted_conversion(e) if {
	e.new_use == "LSE Mehrnutzenhecke"
	e.hedge_or_agroforestry_measure in {"UBB", "BIO", "BIO-Teilbetrieb"}
}

permitted_conversion(e) if {
	e.new_use == "LSE Agroforststreifen"
	e.hedge_or_agroforestry_measure == "1C"
}

control_transfer_exception(e) if {
	e.transferred_control
	e.operator_succession == false
}

# Gründe für OP im Bereich der betroffenen Maßnahme. Amtlich anerkannte
# Ausnahmen sind bei Ermittlung der nicht erfüllten Verpflichtung zu beachten.
op_required_reasons[p.parcel_id] contains reason if {
	some p in input.land.parcels
	some key, reason in {"overlap_public_or_mandatory": "Leistungsüberschneidung", "official_compensation_area": "Behördlicher Ausgleich", "full_contract_unachievable": "Vertrag nicht durchgehend erfüllbar", "sole_external_fault": "Reines Fremdverschulden"}
	p.op_reasons[key]
}

op_required_reasons[p.parcel_id] contains "Übernehmer führt Auflagen nicht bis Jahresende weiter" if {
	some p in input.land.parcels
	p.op_reasons.successor_continues_to_year_end == false
}

op_required_reasons[p.parcel_id] contains "Ernteverpflichtung verfehlt" if {
	some p in input.land.parcels
	p.op_reasons.harvest_obligation_missed
	not drought_harvest_exception(p)
}

max_advance := (input.documentation.payment.approved_annual_eur * 75) / 100 if {
	input.documentation.payment.administrative_checks_complete
	input.documentation.payment.approved_annual_eur >= 0
}

payment_deadline(y) := sprintf("%d-06-30", [y + 1]) if {
	y >= 2023
	y <= 2028
}

over_ceiling(p, y) := max([0, amount - limit.eur_ha]) if {
	some regular in tab.payment_ceilings
	regular.group == "regulär"
	between_years(regular, y)
	some limit in tab.payment_ceilings
	limit.group == p.ceiling_group
	between_years(limit, y)
	is_array(p.stacked_area_payments)
	every pay in p.stacked_area_payments { is_string(pay.measure_code); is_number(pay.eur_per_ha); pay.eur_per_ha >= 0}
	amount := sum([pay.eur_per_ha | some pay in p.stacked_area_payments; not pay.measure_code in regular.excluded_measures])
}

package oepul.o6_17

import data.o17_tables as tab
import rego.v1

# Beide Kataloge verwenden die Artnamen der jeweiligen Quelle.
listed_seed(part) if {
	some row in tab.regional_grass_seed
	row.scientific_name == part.scientific_name
	row.family == part.family
}

valid_seed_part(m, p) if {
	m.certified_ecotype
	is_string(p.scientific_name)
	is_string(p.family)
	p.regional_origin_at_proven
	p.weight_percent > 0
} else if {
	listed_seed(p)
	p.weight_percent > 0
	p.weight_percent <= 5
	p.regional_origin_at_proven
}

weights_within_species_limit(m) if m.certified_ecotype
weights_within_species_limit(m) if {
	every name in {part.scientific_name | some part in m.parts} {
		total := sum([part.weight_percent | some part in m.parts; part.scientific_name == name])
		total <= 5
	}
}

regional_seed(p) if {
	p.land_use == "grassland"
	p.grassland_score >= 30
	p.slope_percent >= 0
	p.slope_percent < 18
	m := p.operations.regional_seed
	m.permanent_div_reseeding
	m.kg_per_ha >= 20
	m.seedbed_prepared
	date_ok(m.sowing_date)
	startswith(m.sowing_date, sprintf("%d-", [input.farm.year]))
	m.sowing_date <= sprintf("%d-05-15", [input.farm.year])
	m.labels_and_invoices
	count({s.scientific_name | some s in m.parts}) >= 30
	count({s.family | some s in m.parts}) >= 7
	weights_within_species_limit(m)
	every part in m.parts { valid_seed_part(m, part) }
}

allowed_disturbance(_, e) if {
	e.minor_deviation
	e.area_m2 >= 0
	e.area_m2 <= 300
	e.kind != "Aufschüttung"
}

allowed_disturbance(_, e) if {
	e.kind == "Aufschüttung"
	e.reseeded
	e.state_law_observed
	e.area_m2 >= 0
	e.area_m2 <= 300
}

allowed_disturbance(_, e) if {
	e.kind == "Aufschüttung"
	e.reseeded
	e.state_law_observed
	e.area_m2 > 300
	e.prior_authorisation
}

allowed_disturbance(_, e) if {
	e.kind == "Schädlingssanierung"
	e.necessary
	e.evidence_retained
}

allowed_disturbance(p, e) if {
	e.kind == "DIVRS-Neueinsaat"
	e.evidence_retained
	companion
	regional_seed(p)
}

# Befunde für gemeldete Vorgänge im ausgewerteten Vertragsjahr.
tillage_breaches contains {"parcel": p.parcel_id, "event": i, "reason": "Grünlandumbruch ohne belegte Ausnahme"} if {
	in_term
	some p in input.land.parcels
	p.land_use == "grassland"
	some i, e in p.operations.grass_events
	e.sward_destroyed
	not allowed_disturbance(p, e)
}

tillage_breaches contains {"parcel": p.parcel_id, "event": i, "reason": "Acker-Grünland-Flächentausch"} if {
	in_term
	some p in input.land.parcels
	some i, e in p.operations.grass_events
	e.kind == "Acker-Grünland-Flächentausch"
}

tillage_breaches contains {"parcel": p.parcel_id, "event": i, "reason": "Gerät für umbruchslose Erneuerung nicht zugelassen"} if {
	in_term
	some p in input.land.parcels
	p.land_use == "grassland"
	some i, e in p.operations.grass_events
	e.kind == "Umbruchslose Erneuerung"
	is_string(e.device)
	not e.device in tab.renewal_tools
}

tillage_breaches contains {"parcel": p.parcel_id, "event": i, "reason": "Ungenutzte Aufschüttung als Sonstige Grünlandflächen beantragen"} if {
	in_term
	some p in input.land.parcels
	p.land_use == "grassland"
	some i, e in p.operations.grass_events
	e.kind == "Aufschüttung"
	e.used_this_year == false
	p.mfa_use != "Sonstige Grünlandflächen"
}

eligible_person(c) if c.operator

eligible_person(c) if {
	c.operational_need
	c.substantially_involved
}

stayed(c) if c.departure_date == null

stayed(c) if {
	date_ok(c.departure_date)
	c.departure_date >= "2025-12-31"
}

credit_course(c, subject) if {
	c.subject == subject
	c.recognised_provider
	c.subject_requirements_met
	eligible_person(c)
	stayed(c)
	c.credited_farms == 1
	c.credited_obligations == 1

	# Auch widersprüchliche interne Buchungen derselben Veranstaltung erkennen.
	subjects := {x.subject | some x in input.documentation.courses; x.person_id == c.person_id; x.event_id == c.event_id}
	count(subjects) == 1
	date_ok(c.date)
	c.date >= "2022-01-01"
	c.date <= "2025-12-31"
	c.hours > 0
}

training_hours(person, subject) := sum([h |
	some event in {c.event_id | some c in input.documentation.courses; c.person_id == person}
	hs := {c.hours | some c in input.documentation.courses; c.person_id == person; c.event_id == event; credit_course(c, subject)}
	count(hs) == 1
	some h in hs
]) if {
	is_array(input.documentation.courses)
}

training_requirements := {"Grünlandbewirtschaftung": 5, "Biodiversität": 3, "Biologische Wirtschaftsweise": 5} if {
	some m in input.farm.o6_17.active_measures
	m in {"BIO", "BIO-Teilbetrieb"}
} else := {"Grünlandbewirtschaftung": 5, "Biodiversität": 3} if companion

training_outstanding contains topic if {
	some topic, hours in training_requirements
	is_array(input.documentation.courses)
	not trained(topic, hours)
}

trained(topic, hours) if {
	some c in input.documentation.courses
	training_hours(c.person_id, topic) >= hours
}

# Überlappende GLÖZ-Verbotsflächen sind je Schlag nur einmal abzuziehen.
soil_ha(p) := p.area_ha - p.gloez_ban_union_ha if {
	p.slope_percent >= 0
	p.slope_percent < 18
	p.gloez_ban_union_ha >= 0
	p.area_ha >= p.gloez_ban_union_ha
}

soil_ha(p) := 0 if p.slope_percent >= 18

required_samples := ceil(sum(values) / 5) if {
	rows := input.land.mfa_2025_grassland
	is_array(rows)
	values := [h | some p in rows; is_number(p.slope_percent); h := soil_ha(p)]
	count(values) == count(rows)
}

sample_mfa_year(s) if s.mfa_year == to_number(substring(s.drawn, 0, 4))

sample_mfa_year(s) if {
	s.autumn_acquisition
	s.mfa_year == to_number(substring(s.drawn, 0, 4)) + 1
}

credited_samples := count({s.sample_id |
	some s in input.documentation.soil_samples
	s.farm_id == input.farm.farm_id
	s.from_eligible_grassland
	date_ok(s.drawn)
	date_ok(s.sent)
	s.drawn >= "2022-01-01"
	s.sent >= s.drawn
	s.sent <= "2025-12-31"
	s.accredited_lab
	s.method in {"Richtlinien für sachgerechte Düngung", "EUF"}
	every k in {"pH", "P", "K", "Humus"} { k in s.analysed_parameters }
	s.gis_recorded
	sample_mfa_year(s)
}) if {
	is_array(input.documentation.soil_samples)
}

sample_deficit := max([0, required_samples - credited_samples])

package oepul.o6_17

import data.o17_tables as tab
import rego.v1

between_years(r, y) if {
	y >= r.first_year
	y <= r.last_year
}

below_upper(_, upper) if upper == null

below_upper(n, upper) if {
	is_number(upper)
	n < upper
}

contract_years(start) := row.years if {
	some row in tab.contract_terms
	row.start == start
}

in_term if {
	contract_years(input.farm.o6_17.start_year) > 0
	input.farm.year >= input.farm.o6_17.start_year
	input.farm.year <= 2028
}

date_ok(d) if is_number(time.parse_rfc3339_ns(sprintf("%sT00:00:00Z", [d])))

timely_application if {
	y := input.farm.o6_17.start_year
	contract_years(y) > 0
	d := input.farm.o6_17.application_date
	date_ok(d)
	d <= sprintf("%d-12-31", [y - 1])
}

companion if {
	some m in input.farm.o6_17.active_measures
	m in tab.companion_measures
}

first_year_land if {
	input.land.grassland_area_ha >= 2
	ln := input.land.agricultural_area_at_ha - input.land.alpine_pasture_area_ha
	ln >= input.land.grassland_area_ha
	100 * input.land.grassland_area_ha >= 40 * ln
}

# MFA-Flächen des laufenden Jahres. Umbruchsverbote oder andere Maßnahmen
# reduzieren den Futterflächennenner nicht.
forage(p) if {
	p.in_austrian_mfa
	p.land_use == "grassland"
}

forage(p) if {
	p.in_austrian_mfa
	p.land_use == "arable"
	some c in tab.forage_crops
	lower(p.crop.crop_name) == lower(c)
}

forage_area := sum([p.area_ha | some p in input.land.parcels; forage(p)]) if {
	is_array(input.land.parcels)
	every p in input.land.parcels {
		is_boolean(p.in_austrian_mfa)
		is_string(p.land_use)
		p.area_ha >= 0
		forage_data_present(p)
	}
}

forage_data_present(p) if p.land_use != "arable"
forage_data_present(p) if is_string(p.crop.crop_name)

cattle_class(breed) := "Zwergrind" if breed in tab.dwarf_breeds

else := "Rind" if is_string(breed)

animal_class(g) := cattle_class(g.breed) if g.kind == "Rind"
animal_class(g) := g.kind if g.kind in {"Schaf", "Ziege"}

animal_class(g) := "Equide klein" if {
	g.kind == "Equide"
	g.breed_height_m > 0
	g.breed_height_m <= 1.48
	g.breed_final_kg > 0
	g.breed_final_kg <= 300
}

animal_class(g) := "Equide groß" if {
	g.kind == "Equide"
	g.breed_height_m > 1.48
}

animal_class(g) := "Equide groß" if {
	g.kind == "Equide"
	g.breed_final_kg > 300
}

animal_class(g) := "Jungwild und junge Neuweltkamele" if {
	g.kind in {"Rotwild", "Damwild und anderes Zuchtwild", "Neuweltkamele"}
	g.age_years < 1
}

animal_class(g) := g.kind if {
	g.kind in {"Rotwild", "Damwild und anderes Zuchtwild", "Neuweltkamele"}
	g.age_years >= 1
}

group_rgve(g) := factor.rgve * g.reference_count if {
	g.in_austria
	g.kind != "Sonstige Nicht-RGVE"
	g.reference_count >= 0
	some factor in tab.rgve_factors
	factor.group == animal_class(g)
	g.age_years >= factor.min_age_years
	below_upper(g.age_years, factor.below_age_years)
}

group_rgve(g) := 0 if g.in_austria == false
group_rgve(g) := 0 if g.kind == "Sonstige Nicht-RGVE"

rgve_total := sum(values) if {
	groups := input.livestock.rgve_groups
	is_array(groups)
	values := [v | some g in groups; v := group_rgve(g)]
	count(values) == count(groups)
}

stocking_density := rgve_total / forage_area if forage_area > 0

# Jahresbezogene Zugangskriterien. In Folgejahren setzt die Bewertung einen
# tatsächlich wirksamen bestehenden Vertrag voraus.
annual_access if {
	in_term
	companion
	input.farm.year == input.farm.o6_17.start_year
	first_year_land
	stocking_density >= 0.3
}

annual_access if {
	in_term
	companion
	input.farm.year > input.farm.o6_17.start_year
	input.farm.o6_17.existing_contract
}

applicant_form_ok if {
	a := input.farm.applicant
	a.public_body_or_institution == false
	a.form in {"natürliche Person", "eingetragene Personengesellschaft"}
}

applicant_form_ok if {
	a := input.farm.applicant
	a.public_body_or_institution == false
	a.form in {"juristische Person", "Personenvereinigung"}
	a.public_share_percent >= 0
	a.public_share_percent <= 25
}

farm_size_ok if input.farm.year > input.farm.first_oepul_year

farm_size_ok if {
	input.farm.year == input.farm.first_oepul_year
	input.land.protected_cultivation_at_ha >= 0.5
}

farm_size_ok if {
	input.farm.year == input.farm.first_oepul_year
	input.land.oepul_minimum_area_at_ha >= 1.5
}

loss_tolerance(previous) := max([0.5, min([5, previous * 0.05])]) if previous >= 0
repayable_loss(previous, reduction) := reduction if reduction > loss_tolerance(previous)

else := 0 if {
	previous >= 0
	reduction >= 0
}

eligible_additions(y, base, new_ha, carried_ha) := new_ha + carried_ha if {
	y in {2024, 2025}
	new_ha >= 0
	carried_ha >= 0
} else := min([new_ha, max([5, base * 0.5])]) + carried_ha if {
	y >= 2026
	y <= 2028
	base >= 0
	new_ha >= 0
	carried_ha >= 0
}

takeover_window(y, d, transferred, additional) if {
	y >= 2023
	y <= 2028
	date_ok(d)
	startswith(d, sprintf("%d-", [y]))
	end := object.get({"2023": "04-17", "2028": "04-17"}, sprintf("%d", [y]), "04-15")
	d <= sprintf("%d-%s", [y, end])
	transferred > 0
	additional >= 0
	additional <= transferred * 0.5
}

applicant_ok if {
	applicant_form_ok
	a := input.farm.applicant
	a.own_name
	a.own_account
	a.disposal_rights
	a.active_farmer
	a.agricultural_activity
}

contract_basis if {
	in_term
	input.farm.o6_17.existing_contract
}

contract_basis if {
	in_term
	timely_application
}

contract_basis if {
	in_term
	t := input.farm.area_movements
	t.previously_participating == false
	t.takeover_approved
	takeover_window(input.farm.year, t.takeover_date, t.transferred_ha, t.additional_ha)
}

# Nur Zugangskriterien. Fachauflagen, Kontrollen und Auszahlung haben eigene Befunde.
access_requirements_met if {
	count(incompatible_pair) == 0
	annual_access
	contract_basis
	applicant_ok
	farm_size_ok
}

exclude_after_cuts if input.documentation.full_cuts_in_contract >= 2

area_movement_assessment := {
	"loss_tolerance_ha": loss_tolerance(m.previous_committed_ha),
	"repayable_loss_ha": repayable_loss(m.previous_committed_ha, m.reduction_without_exception_ha),
	"eligible_additions_and_transfers_ha": eligible_additions(input.farm.year, m.committed_2025_ha, m.cumulative_new_ha, m.carried_commitment_ha),
} if {
	m := input.farm.area_movements
}

package oepul.o6_17

import data.o17_tables as tab
import rego.v1

# Tarife und technische Bruttobeträge vor einzelbetrieblicher Bewilligung.
base_rate(year, score, slope) := row.eur_ha if {
	is_number(slope)
	slope >= 0
	slope < 18
	is_number(score)
	some row in tab.base_rates
	between_years(row, year)
	score >= row.min_score
	below_upper(score, row.below_score)
}

agl_rate(year, slope) := row.eur_ha if {
	is_number(slope)
	some row in tab.agl_rates
	between_years(row, year)
	slope >= row.min_slope
	below_upper(slope, row.below_slope)
}

ban_applies(code) if code in tab.gl_standard_bans

base_amounts[p.parcel_id] := (p.payable_ha - p.payable_ban_union_ha) * rate if {
	in_term
	some p in input.land.parcels
	count(object.get(parcel_exclusions, p.parcel_id, set())) == 0
	p.in_austrian_mfa
	p.land_use == "grassland"
	p.payable_ha >= p.payable_ban_union_ha
	p.payable_ban_union_ha >= 0
	p.area_ha >= p.payable_ha
	rate := base_rate(input.farm.year, p.grassland_score, p.slope_percent)
}

species_match(observed, row) if observed == row.name
species_match(observed, row) if observed == row.annex_h_name
species_match(observed, row) if observed in row.scientific_names

section_qualifies(section, year) if {
	names := {row.name |
		some visit in section.visits
		date_ok(visit.date)
		startswith(visit.date, sprintf("%d-", [year]))
		some obs in visit.observations
		obs.regularly_distributed
		obs.identified
		obs.flowers
		some row in tab.indicator_species
		species_match(obs.name, row)
	}
	count(names) >= 5
}

survey_recorded(s) if {
	s.form_complete
	s.transect_sketch
}

survey_recorded(s) if s.equivalent_records_complete

survey_recorded(s) if {
	s.ama_mfa_photos
	s.identifiable_geolocated_photos
	s.photos_distributed
}

agl_grass(p) if {
	p.in_austrian_mfa
	p.land_use == "grassland"
	p.mown
	p.mfa_use != "Bergmähder"
}

agl_candidate(p, _) if {
	agl_grass(p)
	p.mfa_use in {"Einmähdige Wiese", "Streuwiese"}
}

agl_candidate(p, y) if {
	agl_grass(p)
	p.mfa_use in {"Mähwiese/-weide zwei Nutzungen", "Mähwiese/-weide drei und mehr Nutzungen"}
	"AGL" in p.mfa_codes
	p.first_use == "Mahd"
	s := p.agl_survey
	s.longest_line
	s.edge_distance_m >= 5
	s.approx_two_m_wide
	survey_recorded(s)
	count(s.sections) > 0
	every section in s.sections { section_qualifies(section, y) }
}

agl_cap(y, mown_ha) := max([row.minimum_ha, mown_ha * row.share]) if {
	mown_ha >= 0
	some row in tab.agl_caps
	between_years(row, y)
}

agl_mown_ha := sum([p.area_ha | some p in input.land.parcels; agl_grass(p)]) if is_array(input.land.parcels)

agl_candidates[p.parcel_id] := {"ha": p.payable_ha, "eur_ha": r} if {
	in_term
	some p in input.land.parcels
	count(object.get(parcel_exclusions, p.parcel_id, set())) == 0
	p.area_ha >= p.payable_ha
	p.payable_ha >= 0
	agl_candidate(p, input.farm.year)
	r := agl_rate(input.farm.year, p.slope_percent)
}

agl_payable_area := min([agl_cap(input.farm.year, agl_mown_ha), sum([r.ha | some r in agl_candidates])]) if in_term

# Ohne Verteilungsregel für unterschiedlich tarifierte Flächen ist genau
# die Spanne der möglichen Beträge vor Modulation bestimmbar.
agl_amount_range := {"min_eur": (low * area) + ((high - low) * max([0, area - low_area])), "max_eur": (low * area) + ((high - low) * min([area, high_area]))} if {
	area := agl_payable_area
	rates := {r.eur_ha | some r in agl_candidates}
	count(rates) > 0
	low := min(rates)
	high := max(rates)
	low_area := sum([r.ha | some r in agl_candidates; r.eur_ha == low])
	high_area := sum([r.ha | some r in agl_candidates; r.eur_ha == high])
} else := {"min_eur": 0, "max_eur": 0} if agl_payable_area == 0

combination(a, b) := {"mark": cell.mark, "cell_notes": cell.footnotes, "row_column_notes": notes} if {
	some cell in tab.combination_matrix
	cell.row == a
	cell.column == b
	notes := [n | some n in tab.matrix_notes; applicable_matrix_note(n.number, a, b, cell)]
}

applicable_matrix_note(n, _, _, cell) if n in cell.footnotes
applicable_matrix_note(2, a, b, _) if "13" in {a, b}
applicable_matrix_note(4, a, b, _) if count({a, b} & {"8", "16"}) > 0

ceiling_rows(year) := [r | some r in tab.payment_ceilings; between_years(r, year)]
band_end(b, area) := area if b.up_to_ha == null

else := min([area, b.up_to_ha])

modulation(area) := sum([portion |
	some b in tab.modulation_bands
	portion := max([0, band_end(b, area) - b.above_ha]) * b.factor
]) / area if {
	area > 0
}

sanction_levels(y) := {r.level: r.before_2027 | some r in tab.sanctions} if {
	y >= 2023
	y < 2027
}

else := {r.level: r.from_2027 | some r in tab.sanctions} if y in {2027, 2028}

crop_members(group, y) := {r.name | some r in tab.crop_groups; r.group == group; r.from_year <= y}
program_list(group) := {r.name | some r in tab.program_groups; r.group == group}
public_exceptions(y) := {r.name | some r in tab.public_measures; between_years(r, y)}

switch_listed(a, b, y) if {
	some r in tab.switches
	r.source == a
	r.target == b
	y >= 2023
	y <= r.last_year
}

div_variant(code) := r.conditions if {
	some r in tab.div_variants
	r.code == code
}

div_change(a, b, d) if {
	date_ok(d)
	md := substring(d, 5, 5)
	md > "04-15"
	md <= "06-15"
	a == "DIVSZ"
	b in {"DIVNFZ", "DIVAGF"}
}

div_change(a, b, d) if {
	date_ok(d)
	md := substring(d, 5, 5)
	md > "04-15"
	md <= "08-15"
	a == "DIVNFZ"
	b == "DIVAGF"
}

district_matches(zone, _) if zone.district == "alle Bezirke"
district_matches(zone, p) if zone.district == p.district

drought_harvest_exception(p) if {
	input.farm.year == 2026
	p.land_use == "arable"
	p.harvest_drought.usual_late_harvest
	p.harvest_drought.heat_drought_affected
	p.harvest_drought.no_harvestable_stand
	date_ok(p.harvest_drought.assessment_date)
	startswith(p.harvest_drought.assessment_date, "2026-")
	some zone in tab.harvest_drought_districts
	p.harvest_drought.assessment_date >= zone.from_date
	zone.state == p.federal_state
	district_matches(zone, p)
}

# Für ein unvollständiges Ausgangsprofil werden nur belegte Einzelergebnisse
# ausgewiesen. Eine betriebliche Betragsprojektion verlangt vollständige
# Bezugsflächen und positive Zugangsprüfung.
premium_input_gaps contains {"bereich": "Betrieb", "angabe": "MFA-Schlagliste"} if not is_array(input.land.parcels)

premium_input_gaps contains {"bereich": "Schlag", "index": i, "angabe": "Inlands-MFA oder Nutzungsart"} if {
	some i, p in input.land.parcels
	not parcel_scope_known(p)
}

parcel_scope_known(p) if {
	is_boolean(p.in_austrian_mfa)
	is_string(p.land_use)
}

premium_input_gaps contains {"bereich": "Grünland", "index": i, "angabe": k} if {
	some i, p in input.land.parcels
	p.in_austrian_mfa
	p.land_use == "grassland"
	some k in {"area_ha", "payable_ha", "slope_percent"}
	not is_number(object.get(p, k, null))
}

premium_input_gaps contains {"bereich": "Grünland", "index": i, "angabe": "Mahd und MFA-Schlagnutzung"} if {
	some i, p in input.land.parcels
	p.in_austrian_mfa
	p.land_use == "grassland"
	not mowing_known(p)
}

mowing_known(p) if {
	is_boolean(p.mown)
	is_string(p.mfa_use)
}

premium_input_gaps contains {"bereich": "Grundprämie", "index": i, "angabe": k} if {
	some i, p in input.land.parcels
	p.in_austrian_mfa
	p.land_use == "grassland"
	is_number(p.slope_percent)
	p.slope_percent < 18
	p.payable_ha > 0
	some k in {"grassland_score", "payable_ban_union_ha"}
	not is_number(object.get(p, k, null))
}

premium_input_gaps contains {"bereich": "Grünland", "index": i, "angabe": "Förderfläche außerhalb der Schlagfläche"} if {
	some i, p in input.land.parcels
	p.in_austrian_mfa
	p.land_use == "grassland"
	p.payable_ha > p.area_ha
}

premium_input_gaps contains {"bereich": "Grundprämie", "index": i, "angabe": "Verbotsfläche über Förderfläche"} if {
	some i, p in input.land.parcels
	p.in_austrian_mfa
	p.land_use == "grassland"
	is_number(p.payable_ban_union_ha)
	p.payable_ban_union_ha > p.payable_ha
}

premium_input_gaps contains {"bereich": "AGL", "index": i, "angabe": "Jahrescodes"} if {
	some i, p in input.land.parcels
	agl_grass(p)
	p.mfa_use in {"Mähwiese/-weide zwei Nutzungen", "Mähwiese/-weide drei und mehr Nutzungen"}
	not is_array(p.mfa_codes)
}

premium_input_gaps contains {"bereich": "AGL", "index": i, "angabe": "Erhebungsdaten oder erste Nutzungsart"} if {
	some i, p in input.land.parcels
	agl_grass(p)
	"AGL" in p.mfa_codes
	p.mfa_use in {"Mähwiese/-weide zwei Nutzungen", "Mähwiese/-weide drei und mehr Nutzungen"}
	not survey_available(p)
}

survey_available(p) if {
	is_string(p.first_use)
	is_array(p.agl_survey.sections)
}

premium_projection := {
	"grundpraemie_eur": sum([v | some v in base_amounts]),
	"agl_ha": agl_payable_area,
	"agl_eur": agl_amount_range,
	"modulationsfaktor_heim": modulation(input.farm.home_area_ha),
} if {
	access_requirements_met
	count(premium_input_gaps) == 0
}

matrix_measure(code) := row if {
	some row in tab.matrix_measures
	row.code == code
}

combination_in_year(a, b, y) := combination(a, b) if {
	y >= matrix_measure(a).first_year
	y >= matrix_measure(b).first_year
	y <= 2028
	a != b
}

# Bei den expliziten Gattungsangaben umfasst die Kennart auch einen
# eindeutig bestimmten binomischen Namen dieser Gattung.
species_match(observed, row) if {
	some listed in row.scientific_names
	endswith(listed, " sp.")
	genus := trim_suffix(listed, " sp.")
	regex.match(sprintf("^%s [a-z][a-z-]+$", [genus]), observed)
}

